import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import PageStructure from 'flarum/forum/components/PageStructure';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import humanTime from 'flarum/common/helpers/humanTime';
import extractText from 'flarum/common/utils/extractText';
import { approve, queue, removeScore } from '../../common/api';
import { formatScore } from '../../common/format';
import ArcadeHero from '../components/ArcadeHero';
import { personLink } from '../components/Person';
import { t } from '../t';

/** /arcade/moderate — scores held back: outliers, and crowns waiting for approval. */
export default class ModeratePage extends Page {
  rows = [];
  next = null;
  loading = true;
  busy = null;
  oninit(vnode) {
    super.oninit(vnode);
    app.setTitle(extractText(t('moderate.title')));
    app.history.push('insert-coin.moderate', extractText(t('moderate.title')));
    // Nobody else gets an answer from the queue: don't ask.
    if (app.forum.attribute('canModerateArcade')) this.load();
  }
  load(more = false) {
    this.loading = true;
    queue(more && this.next ? this.next : 0).then(r => {
      this.rows = more ? [...this.rows, ...r.data] : r.data;
      this.next = r.meta.next;
      this.loading = false;
      m.redraw();
    }, () => {
      this.loading = false;
      m.redraw();
    });
  }
  act(row, action) {
    this.busy = row.id;
    action(row.id).then(() => {
      this.rows = this.rows.filter(r => r.id !== row.id);
      this.busy = null;
      m.redraw();
    }, () => {
      this.busy = null;
      m.redraw();
    });
  }
  view() {
    if (!app.forum.attribute('canModerateArcade')) {
      return m(PageStructure, {
        className: "InsertCoinPage",
        sidebar: () => m(IndexSidebar, null)
      }, m("p", {
        className: "InsertCoinEmpty"
      }, t('moderate.forbidden')));
    }
    return m(PageStructure, {
      className: "InsertCoinPage InsertCoinModeratePage",
      hero: () => m(ArcadeHero, {
        title: t('moderate.title'),
        subtitle: t('moderate.subtitle')
      }),
      sidebar: () => m(IndexSidebar, null)
    }, m("ul", {
      className: "InsertCoinQueue"
    }, this.rows.map(row => m("li", {
      className: "InsertCoinQueue-row"
    }, personLink(row.user), m("div", {
      className: "InsertCoinQueue-what"
    }, row.game ? m(Link, {
      href: app.route('insert-coin.game', {
        slug: row.game.slug
      })
    }, row.game.title) : null, m("b", null, formatScore(row.score, row.game?.scoreLabel)), m("span", {
      className: "InsertCoinQueue-meta"
    }, t('moderate.reason_' + (row.reason || 'outlier')), " \xB7", ' ', t('moderate.champion_score', {
      score: formatScore(row.game?.championScore, row.game?.scoreLabel)
    }), " \xB7", ' ', t('moderate.duration', {
      seconds: row.duration
    }), " \xB7 ", humanTime(new Date(row.at)))), m("div", {
      className: "InsertCoinQueue-actions"
    }, m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-check",
      loading: this.busy === row.id,
      onclick: () => this.act(row, approve)
    }, t('moderate.approve')), m(Button, {
      className: "Button",
      icon: "far fa-trash-can",
      disabled: this.busy === row.id,
      onclick: () => this.act(row, removeScore)
    }, t('moderate.reject')))))), this.loading ? m(LoadingIndicator, {
      display: "block"
    }) : null, !this.loading && !this.rows.length ? m("p", {
      className: "InsertCoinEmpty"
    }, t('moderate.empty')) : null, !this.loading && this.next ? m(Button, {
      className: "Button",
      onclick: () => this.load(true)
    }, t('board.more')) : null);
  }
}
flarum.reg.add('ernestdefoe-insert-coin', 'forum/pages/ModeratePage', ModeratePage);