import Hero from 'flarum/forum/components/Hero';
import Icon from 'flarum/common/components/Icon';
import ItemList from 'flarum/common/utils/ItemList';
/**
 * The arcade's hero, built like core's own (Hero, Hero-title, Hero-subtitle),
 * so every theme styles it the way it styles the welcome hero.
 */
export default class ArcadeHero extends Hero {
  className() {
    return 'InsertCoinHero';
  }
  bodyItems() {
    const items = new ItemList();
    items.add('content', m("div", {
      className: "containerNarrow"
    }, m("h1", {
      className: "Hero-title"
    }, m(Icon, {
      name: "fas fa-gamepad"
    }), " ", this.attrs.title), this.attrs.subtitle ? m("div", {
      className: "Hero-subtitle"
    }, this.attrs.subtitle) : null), 80);
    return items;
  }
}
flarum.reg.add('ernestdefoe-insert-coin', 'forum/components/ArcadeHero', ArcadeHero);